    worksheet.getRow(1).height = 20;
    worksheet.getRow(2).height = 20;
    worksheet.getRow(3).height = 20;
    worksheet.getRow(4).height = 30; // Tiêu đề báo cáo
    worksheet.getRow(5).height = 20; // Ngày tháng

    // 1. Chèn Logo
    try {
      const imageId = workbook.addImage({
        base64: LOGO_BASE64,
        extension: 'png',
      });
      // Gộp ô A1:D3 cho Logo
      worksheet.mergeCells('A1:D3');
      worksheet.addImage(imageId, {
        tl: { col: 0.15, row: 0.15 },
        ext: { width: 138, height: 48 },
        editAs: 'oneCell'
      });
    } catch (err) {
      console.error("Lỗi khi thêm logo vào Excel:", err);
    }

    // 2. Chèn thông tin đơn vị hành chính bên phải (Cột E đến Q)
    worksheet.mergeCells('E1:Q1');
